72:         3: 'red',
73:         4: 'yellow',
74:         5: 'yellow',
75:         6: 'black',
76:         9: 'red',
77:         undefined: 'yellow'
78:       }
79:     }
80:   },
81:   created() {
82:     this.getList()
83:   },
84:   methods: {
85:     notifyDrawerWidth() {
86:       this.$emit('drawer-width-change', computeApprovalDrawerWidth(this.stepList))
87:     },
88:     resolveDataId() {
89:       return this.dataId != null && this.dataId !== '' ? this.dataId : this.getId()
90:     },
91:     async getList() {
92:       const dataId = this.resolveDataId()
93:       if (!this.busCode || !dataId) {
94:         this.stepList = []
95:         this.notifyDrawerWidth()
96:         return
97:       }
98:       // 获取节点
99:       this.$post('/flowable/task/taskAllNodes', {
100:         busCode: this.busCode,
101:         dataId
102:       }).then((res) => {
103:         if (res.code == 200 && res.data?.length) {
104:           return res.data
105:         }
106:       }).then((res1) => {
107:         // 获取节点状态：是否已完成
108:         return this.$post('/flowable/task/flowViewer', {
109:           busCode: this.busCode,
110:           dataId
111:         }).then((res2) => {
112:           const unCompleteNode = res2?.data?.find((item) => !item.completed)
113:           if (unCompleteNode) {
114:             unCompleteNode.key = unCompleteNode.subProcessKey && !unCompleteNode.showSubProcessDetails ? unCompleteNode.subProcessKey : unCompleteNode.key
115:           }
116:           this.stepList = res1?.map((item, index, arr) => {
117:             item.completed = true
118:             this.activeStep = arr.length - 1
119:             if (unCompleteNode?.key == item.targetKey) {
120:               this.activeStep = index
121:               unCompleteNode.taskName = item.taskName
122:               item.completed = false
123:             }
124: 
125:             return item
126:           }) || []
127:           this.$nextTick(this.notifyDrawerWidth)
128: 
129:           return unCompleteNode
130:         })
131:       }).then((node) => {
132:         // 获取时间线详情
133:         this.$post('/flowable/task/flowRecord', {
134:           busCode: this.busCode,
135:           dataId
136:         }).then((res) => {
137:           if (res.code == 200) {
138:             this.flowList = node ? res.data.flowList.concat([{ ...node, comment: {} }]) : res.data.flowList
139:           }
140:         })
141:       })
142:     }
143:   }
144: }
145: </script>
