const { chromium } = require('@playwright/test');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1400, height: 900 } });
  const file = 'file:///' + path.resolve(__dirname, 'harness.html').replace(/\\/g, '/');
  await page.goto(file);

  async function measure(mode) {
    await page.evaluate((m) => { document.body.setAttribute('data-mode', m); }, mode);
    return await page.evaluate(() => {
      const content = document.getElementById('content');
      const hdr = document.getElementById('hdr');
      const panel = document.querySelector('.attachment-drawer-panel');
      const drawerBody = document.querySelector('.el-drawer__body');
      const cs = getComputedStyle(content);
      const contentRect = content.getBoundingClientRect();
      const hdrRect = hdr.getBoundingClientRect();
      const drawerRect = drawerBody.getBoundingClientRect();
      return {
        overflowY: cs.overflowY,
        contentScrollH: content.scrollHeight,
        contentClientH: content.clientHeight,
        contentScrollable: content.scrollHeight > content.clientHeight + 1,
        headerTop: Math.round(hdrRect.top),
        headerVisible: hdrRect.height > 0 && hdrRect.top >= drawerRect.top - 1 && hdrRect.bottom <= drawerRect.bottom + 1,
        contentBottomOverflow: Math.round(contentRect.bottom - drawerRect.bottom), // >0 means content extends past visible drawer body
        drawerBodyScrollTop: drawerBody.scrollTop,
        drawerBodyScrollable: drawerBody.scrollHeight > drawerBody.clientHeight + 1,
      };
    });
  }

  const oldM = await measure('old');
  const newM = await measure('new');
  console.log('OLD =', JSON.stringify(oldM, null, 2));
  console.log('NEW =', JSON.stringify(newM, null, 2));

  // 断言：新样式下时间线区域内部可滚动，头步骤条可见且不被裁切
  const pass = newM.overflowY === 'auto' && newM.contentScrollable && newM.headerVisible;
  console.log('VERDICT =', pass ? 'PASS' : 'FAIL');

  await browser.close();
  process.exit(pass ? 0 : 1);
})();

