const { chromium } = require('@playwright/test');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1400, height: 900 } });
  const file = 'file:///' + path.resolve(__dirname, 'harness2.html').replace(/\\/g, '/');
  await page.goto(file);

  async function measure(fix) {
    await page.evaluate((f) => document.body.setAttribute('data-drawer-fix', f), fix);
    return await page.evaluate(() => {
      const drawer = document.getElementById('drawer');
      const drawerBody = document.querySelector('.el-drawer__body');
      const content = document.getElementById('content');
      const hdr = document.getElementById('hdr');
      const vh = window.innerHeight;
      const dRect = drawer.getBoundingClientRect();
      const cRect = content.getBoundingClientRect();
      const hRect = hdr.getBoundingClientRect();
      // 抽屉底部是否超出视口（>0 表示被裁掉，底部内容不可达）
      const drawerOverflowViewport = Math.round(dRect.bottom - vh);
      // 时间线最后一条是否可滚动到可见
      const lastItem = content.lastElementChild;
      const lastRect = lastItem.getBoundingClientRect();
      // 尝试把 content 滚到底，看最后一条是否进入 drawerBody 可视区
      content.scrollTop = content.scrollHeight;
      const lastRectAfter = lastItem.getBoundingClientRect();
      const bodyRect = drawerBody.getBoundingClientRect();
      const lastVisibleAfterScroll = lastRectAfter.bottom <= bodyRect.bottom + 1 && lastRectAfter.top >= bodyRect.top - 1;
      return {
        drawerBottom: Math.round(dRect.bottom),
        viewportH: vh,
        drawerOverflowViewport,
        contentScrollable: content.scrollHeight > content.clientHeight + 1,
        lastItemInitiallyVisible: lastRect.bottom <= bodyRect.bottom + 1,
        lastVisibleAfterScroll,
        headerTopInsideBody: hRect.top >= bodyRect.top - 1,
      };
    });
  }

  const off = await measure('off');
  const on = await measure('on');
  console.log('DRAWER-FIX OFF (现状) =', JSON.stringify(off, null, 2));
  console.log('DRAWER-FIX ON  (修复后) =', JSON.stringify(on, null, 2));
  const pass = off.drawerOverflowViewport > 0 && on.drawerOverflowViewport <= 0;
  console.log('ROOT-CAUSE CONFIRMED =', pass ? 'YES (抽屉向下超出视口被裁切)' : 'NO');
  await browser.close();
  process.exit(0);
})();

