  const file = 'file:///' + path.resolve(__dirname, 'real-harness.html').replace(/\\/g,'/');
  await page.goto(file, { waitUntil: 'networkidle' });
  const res = await page.evaluate(() => {
    const drawer = document.getElementById('drawer');
    const body = document.querySelector('.el-drawer__body');
    const content = document.getElementById('content');
    const hdr = document.getElementById('hdr');
    const vh = window.innerHeight;
    const dRect = drawer.getBoundingClientRect();
    const bRect = body.getBoundingClientRect();
    const cStyle = getComputedStyle(drawer);
    // 滚到底，看最后一条能否进入 body 可视区
    content.scrollTop = content.scrollHeight;
    const last = content.lastElementChild.getBoundingClientRect();
    return {
      drawerComputedHeight: cStyle.height,
      drawerTop: Math.round(dRect.top),
      drawerBottom: Math.round(dRect.bottom),
      viewportH: vh,
      drawerOverflowViewport: Math.round(dRect.bottom - vh),
      contentScrollable: content.scrollHeight > content.clientHeight + 1,
      lastRowVisibleAfterScroll: last.bottom <= bRect.bottom + 1 && last.top >= bRect.top - 1,
      headerVisible: hdr.getBoundingClientRect().height > 0,
    };
  });
  console.log(JSON.stringify(res, null, 2));
  // 截图存档
  await page.evaluate(() => { document.getElementById('content').scrollTop = 0; });
  await page.screenshot({ path: path.resolve(__dirname, 'deployed-fix-screenshot.png') });
  await browser.close();
  const pass = res.drawerOverflowViewport <= 0 && res.contentScrollable && res.lastRowVisibleAfterScroll && res.headerVisible;
  console.log('PASS =', pass);
  process.exit(pass ? 0 : 1);
})();

