  async function measure(mode) {
    // mode=old: 强制旧样式（top 下移但 height 仍 100%）；new: 用部署 CSS（已修复）
    await page.evaluate((m) => {
      let s = document.getElementById('__override');
      if (!s) { s = document.createElement('style'); s.id = '__override'; document.head.appendChild(s); }
      s.textContent = m === 'old'
        ? '.attachment .el-drawer{ top: var(--navbar-height,88px); height:100% !important; }'
        : '.attachment .el-drawer{ top: var(--navbar-height,88px); height:calc(100% - var(--navbar-height,88px)) !important; }';
    }, mode);
    await page.waitForTimeout(50);
    return await page.evaluate(() => {
      const wrapper = document.getElementById('wrapper');
      const drawer = document.getElementById('drawer');
      const body = document.querySelector('.el-drawer__body');
      const content = document.getElementById('content');
      const vh = window.innerHeight;
      const wRect = wrapper.getBoundingClientRect();
      const dRect = drawer.getBoundingClientRect();
      const bRect = body.getBoundingClientRect();
      // 滚到底看最后一条
      content.scrollTop = content.scrollHeight;
      const last = content.lastElementChild.getBoundingClientRect();
      const lastReachable = last.bottom <= bRect.bottom + 1 && last.top >= bRect.top - 1;
      return {
        drawerTop: Math.round(dRect.top),
        drawerBottom: Math.round(dRect.bottom),
        wrapperBottom: Math.round(wRect.bottom),
        viewportH: vh,
        drawerClippedByWrapper: Math.round(dRect.bottom - wRect.bottom), // >0 表示底部被 wrapper 裁掉
        contentScrollable: content.scrollHeight > content.clientHeight + 1,
        lastRowReachable: lastReachable,
      };
    });
  }
  const oldM = await measure('old');
  const newM = await measure('new');
  console.log('OLD(现状) =', JSON.stringify(oldM));
  console.log('NEW(修复) =', JSON.stringify(newM));
  const pass = oldM.drawerClippedByWrapper > 0 && newM.drawerClippedByWrapper <= 0 && newM.contentScrollable && newM.lastRowReachable;
  console.log('ROOT-CAUSE & FIX CONFIRMED =', pass ? 'YES' : 'NO');
  await browser.close();
})();

